INSERT INTO lessons (id,course_id,lesson_number,title,short_description,introduction,explanation,applications_json,examples_json,exercises_json,quiz_json) VALUES (1,1,1,'Introduction to HTML','What is HTML and why it is important?','HTML (HyperText Markup Language) is the standard language used to create the structure of web pages.','HTML uses elements and tags to tell the browser how to display content such as headings, paragraphs, links, and images. It is the foundation of every website and works together with CSS and JavaScript.','["Creating website structure","Displaying text, images, and links","Building forms and web page layouts"]','[{"code":"\u003c!DOCTYPE html\u003e\n\u003chtml\u003e\n  \u003cbody\u003e\n    \u003ch1\u003eHello LEARNHUB\u003c/h1\u003e\n    \u003cp\u003eMy first web page.\u003c/p\u003e\n  \u003c/body\u003e\n\u003c/html\u003e","title":"Simple HTML"}]','["What does HTML stand for?","Write a simple HTML page with a heading and paragraph."]','{"answer":0,"question":"What does HTML stand for?","explanation":"HTML stands for HyperText Markup Language.","options":["HyperText Markup Language","HighText Machine Language","Hyperlink and Text Markup Language","Home Tool Markup Language"]}');
INSERT INTO lessons (id,course_id,lesson_number,title,short_description,introduction,explanation,applications_json,examples_json,exercises_json,quiz_json) VALUES (2,1,2,'HTML Structure','The basic structure of an HTML document.','Every HTML document follows a standard structure that helps browsers understand the page.','The basic structure includes <!DOCTYPE html>, <html>, <head>, and <body>. The head contains metadata and the title, while the body contains visible content.','["Creating valid web pages","Organizing metadata and page content","Making pages easier for browsers to interpret"]','[{"code":"\u003c!DOCTYPE html\u003e\n\u003chtml\u003e\n\u003chead\u003e\n  \u003ctitle\u003eMy Page\u003c/title\u003e\n\u003c/head\u003e\n\u003cbody\u003e\n  \u003ch1\u003eWelcome\u003c/h1\u003e\n\u003c/body\u003e\n\u003c/html\u003e","title":"Basic Structure"}]','["Create an HTML file with head and body sections.","Add a title to your page."]','{"answer":2,"question":"Which tag contains the visible page content?","explanation":"The \u003cbody\u003e tag contains the visible content of the page.","options":["\u003chead\u003e","\u003cmeta\u003e","\u003cbody\u003e","\u003ctitle\u003e"]}');
INSERT INTO lessons (id,course_id,lesson_number,title,short_description,introduction,explanation,applications_json,examples_json,exercises_json,quiz_json) VALUES (3,1,3,'HTML Elements and Tags','Common HTML elements and their usage.','HTML elements are building blocks made of tags that define different parts of content.','Most elements have an opening tag, content, and a closing tag. Examples include headings, paragraphs, links, images, and containers.','["Formatting content","Adding links and images","Structuring sections of a page"]','[{"code":"\u003ch1\u003eMain Title\u003c/h1\u003e\n\u003cp\u003eThis is a paragraph.\u003c/p\u003e\n\u003ca href=\"https://example.com\"\u003eVisit\u003c/a\u003e","title":"Elements"}]','["Create a page using h1, p, and a tags.","Explain the difference between an opening and closing tag."]','{"answer":0,"question":"Which element is used for a paragraph?","explanation":"The \u003cp\u003e tag defines a paragraph.","options":["\u003cp\u003e","\u003cdiv\u003e","\u003cimg\u003e","\u003ch1\u003e"]}');
INSERT INTO lessons (id,course_id,lesson_number,title,short_description,introduction,explanation,applications_json,examples_json,exercises_json,quiz_json) VALUES (4,1,4,'HTML Attributes','Adding attributes to HTML elements.','Attributes provide additional information about HTML elements.','Attributes are written inside the opening tag and usually come in name/value pairs like href, src, alt, class, and id.','["Configuring links and images","Styling and identifying elements","Improving accessibility with alt text"]','[{"code":"\u003cimg src=\"logo.png\" alt=\"LEARNHUB logo\"\u003e\n\u003ca href=\"courses.html\" class=\"btn\"\u003eCourses\u003c/a\u003e","title":"Attributes"}]','["Add alt text to an image.","Create a link with href and class attributes."]','{"answer":2,"question":"Which attribute provides alternative text for an image?","explanation":"The alt attribute provides alternative text for images.","options":["src","title","alt","href"]}');
INSERT INTO lessons (id,course_id,lesson_number,title,short_description,introduction,explanation,applications_json,examples_json,exercises_json,quiz_json) VALUES (5,1,5,'Links and Images','Working with links and images.','Links and images make web pages connected and visual.','The <a> tag creates hyperlinks using href, while the <img> tag embeds images using src and alt. Links can open pages, files, or sections.','["Navigation menus","Image galleries","Linking to resources and pages"]','[{"code":"\u003ca href=\"https://learnhub.example\"\u003eVisit LEARNHUB\u003c/a\u003e\n\u003cimg src=\"banner.jpg\" alt=\"Course banner\"\u003e","title":"Link and Image"}]','["Create a link to another page.","Insert an image with meaningful alt text."]','{"answer":1,"question":"Which tag creates a hyperlink?","explanation":"The \u003ca\u003e tag creates hyperlinks.","options":["\u003clink\u003e","\u003ca\u003e","\u003chref\u003e","\u003curl\u003e"]}');
INSERT INTO lessons (id,course_id,lesson_number,title,short_description,introduction,explanation,applications_json,examples_json,exercises_json,quiz_json) VALUES (6,1,6,'Tables and Lists','Creating tables and lists.','Tables and lists organize information clearly.','Lists use <ul>, <ol>, and <li>. Tables use <table>, <tr>, <th>, and <td> to represent rows and columns of data.','["Displaying schedules and data","Creating navigation or feature lists","Organizing structured information"]','[{"code":"\u003cul\u003e\u003cli\u003eHTML\u003c/li\u003e\u003cli\u003eCSS\u003c/li\u003e\u003c/ul\u003e\n\u003ctable\u003e\u003ctr\u003e\u003cth\u003eCourse\u003c/th\u003e\u003cth\u003eHours\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eHTML\u003c/td\u003e\u003ctd\u003e8\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e","title":"List and Table"}]','["Create an ordered list of 3 courses.","Create a table with two columns and two rows."]','{"answer":2,"question":"Which tag defines a table row?","explanation":"The \u003ctr\u003e tag defines a table row.","options":["\u003ctd\u003e","\u003cth\u003e","\u003ctr\u003e","\u003ctable\u003e"]}');
INSERT INTO lessons (id,course_id,lesson_number,title,short_description,introduction,explanation,applications_json,examples_json,exercises_json,quiz_json) VALUES (7,1,7,'HTML Forms','Collecting user input with forms.','Forms allow users to send data to a website, such as login details, messages, or survey responses.','HTML forms use <form>, <input>, <label>, <textarea>, and <button>. Proper labels and input types improve usability and accessibility.','["Login and registration pages","Contact forms","Search and feedback forms"]','[{"code":"\u003cform\u003e\n  \u003clabel\u003eEmail\u003c/label\u003e\n  \u003cinput type=\"email\" name=\"email\"\u003e\n  \u003cbutton type=\"submit\"\u003eSend\u003c/button\u003e\n\u003c/form\u003e","title":"Form"}]','["Create a simple contact form.","Add labels for each input field."]','{"answer":2,"question":"Which tag is used to create an HTML form?","explanation":"The \u003cform\u003e tag creates a form.","options":["\u003cinput\u003e","\u003clabel\u003e","\u003cform\u003e","\u003cbutton\u003e"]}');
INSERT INTO lessons (id,course_id,lesson_number,title,short_description,introduction,explanation,applications_json,examples_json,exercises_json,quiz_json) VALUES (8,1,8,'Semantic HTML','Using semantic tags for better web pages.','Semantic HTML uses meaningful tags that describe the purpose of content.','Elements like <header>, <nav>, <main>, <section>, <article>, and <footer> improve readability, accessibility, and SEO.','["Accessible page layouts","SEO-friendly websites","Maintainable code structure"]','[{"code":"\u003cheader\u003eSite Header\u003c/header\u003e\n\u003cmain\u003e\n  \u003csection\u003e\n    \u003carticle\u003eLesson content\u003c/article\u003e\n  \u003c/section\u003e\n\u003c/main\u003e\n\u003cfooter\u003eFooter\u003c/footer\u003e","title":"Semantic Layout"}]','["Convert a div-based layout to semantic tags.","Identify where \u003cmain\u003e and \u003cfooter\u003e should be used."]','{"answer":1,"question":"Which tag represents the main content of a page?","explanation":"The \u003cmain\u003e tag represents the main content.","options":["\u003csection\u003e","\u003cmain\u003e","\u003cdiv\u003e","\u003caside\u003e"]}');
INSERT INTO lessons (id,course_id,lesson_number,title,short_description,introduction,explanation,applications_json,examples_json,exercises_json,quiz_json) VALUES (9,2,1,'Introduction to CSS - Styling the Web','What CSS - Styling the Web is and why it matters','This lesson introduces CSS - Styling the Web and its role in Programming.','Learn how to style beautiful, responsive web pages with CSS. You will learn the core purpose, key terms, and where this topic is used in real-world situations.','["Understanding core concepts","Identifying real-world uses","Building a foundation for advanced lessons"]','[{"code":"CSS - Styling the Web - Key ideas\n1. Purpose\n2. Core concepts\n3. Practical use","title":"CSS - Styling the Web Overview"}]','["Define CSS - Styling the Web in your own words.","List three uses of CSS - Styling the Web."]','{"answer":0,"question":"What is the main goal of learning ","explanation":"Learning CSS - Styling the Web builds understanding and practical skills.","options":["To understand its core concepts and apply them","To avoid using technology","To replace all other courses","To memorize random terms only"]}');
INSERT INTO lessons (id,course_id,lesson_number,title,short_description,introduction,explanation,applications_json,examples_json,exercises_json,quiz_json) VALUES (10,2,2,'CSS - Styling the Web Fundamentals','Core concepts and terminology','Learn the essential building blocks of CSS - Styling the Web.','This lesson covers the fundamental concepts, common terminology, and basic rules you need before moving to practical work in CSS - Styling the Web.','["Building vocabulary","Understanding basic rules","Preparing for hands-on practice"]','[{"code":"Example: Apply a basic CSS - Styling the Web concept in a simple scenario.","title":"Fundamentals"}]','["Write down five key terms from CSS - Styling the Web.","Explain one fundamental concept."]','{"answer":0,"question":"Why are fundamentals important in ","explanation":"Fundamentals provide the base for advanced skills.","options":["They provide a base for advanced skills","They are optional","They replace practice","They are only for exams"]}');
INSERT INTO lessons (id,course_id,lesson_number,title,short_description,introduction,explanation,applications_json,examples_json,exercises_json,quiz_json) VALUES (11,2,3,'Working with CSS - Styling the Web','Practical skills and workflow','Apply CSS - Styling the Web through practical steps and workflows.','You will learn a simple workflow for using CSS - Styling the Web effectively, including common tools, steps, and best practices.','["Following a practical workflow","Using common tools","Applying best practices"]','[{"code":"Step 1: Plan\nStep 2: Apply CSS - Styling the Web concept\nStep 3: Review result","title":"Workflow"}]','["Describe a simple workflow for CSS - Styling the Web.","Identify one best practice."]','{"answer":0,"question":"What helps make work in CSS - Styling the Web effective?","explanation":"A clear workflow and best practices improve effectiveness.","options":["A clear workflow and best practices","Skipping planning","Ignoring results","Avoiding practice"]}');
INSERT INTO lessons (id,course_id,lesson_number,title,short_description,introduction,explanation,applications_json,examples_json,exercises_json,quiz_json) VALUES (12,2,4,'CSS - Styling the Web Examples and Practice','Learn by doing','Examples help connect theory to practice in CSS - Styling the Web.','This lesson walks through examples and practice tasks so you can apply what you learned and build confidence.','["Solving practical problems","Learning from examples","Building confidence"]','[{"code":"Practice: create a small example using CSS - Styling the Web and review the outcome.","title":"Practice Example"}]','["Complete a small practice task for CSS - Styling the Web.","Explain what you learned from the example."]','{"answer":0,"question":"Why are examples useful when learning ","explanation":"Examples show how concepts work in practice.","options":["They show how concepts work in practice","They remove the need to learn","They make concepts unclear","They are only decorative"]}');
