INSERT INTO lessons (id,course_id,lesson_number,title,short_description,introduction,explanation,applications_json,examples_json,exercises_json,quiz_json) VALUES (218,36,6,'Kinyarwanda Project and Next Steps','Apply your skills','Use what you learned in a small Kinyarwanda project.','In this final lesson, you combine concepts into a practical mini-project and identify the next course to continue your learning path.','["Mini projects","Real-world application","Preparing for the next course"]','[{"code":"Project: Build a small Kinyarwanda deliverable using the concepts from this course.","title":"Mini Project"}]','["Create a small project using Kinyarwanda.","List what you want to learn next."]','{"answer":0,"question":"What is a good next step after finishing ","explanation":"Applying skills and continuing learning reinforces progress.","options":["Apply skills in a project and continue learning","Stop practicing","Delete your notes","Skip fundamentals"]}');
